        self.val = val
        self.next = next

def merge_k_lists(lists):
    heap = []
    for i, node in enumerate(lists):
        if node:
            heapq.heappush(heap, (node.val, i, node))
    dummy = ListNode()
    cur = dummy
    while heap:
        _, i, node = heapq.heappop(heap)
        cur.next = node
        cur = cur.next
        if node.next:
            heapq.heappush(heap, (node.next.val, i, node.next))
    return dummy.next

# Example: merge_k_lists([list(1->4->5), list(1->3->4), list(2->6)]) -> 1->1->2->3->4->4->5->6
# Time: O(N log k), Space: O(k) heap. Min-heap always yields the smallest current head.

