    place = 1
    while head:
        num += head.val * place
        place *= 10
        head = head.next
    return num

def to_list(num):
    if num == 0:
        return ListNode(0)
    dummy = ListNode()
    cur = dummy
    while num:
        cur.next = ListNode(num % 10)
        cur = cur.next
        num //= 10
    return dummy.next

def multiply_two_lists(l1, l2):
